    return wb.active


def parse_datetime(v, allow_serial=True):
    """Coerce a cell value (datetime, date, string, Excel serial) to datetime."""
    if v is None:
        return None
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        fmts = ("%m/%d/%Y", "%m/%d/%y", "%d/%m/%Y", "%d/%m/%y",
                "%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y", "%d.%m.%Y",
                "%d %b %Y", "%d-%b-%Y", "%b %d, %Y", "%B %d, %Y",
                "%m/%d/%Y %H:%M:%S", "%d/%m/%Y %H:%M:%S")
        for f in fmts:
            try:
                return datetime.strptime(s, f)
            except ValueError:
                continue
        try:
            return datetime.fromisoformat(s)
        except ValueError:
            return None
    if allow_serial and isinstance(v, (int, float)):
        try:
            return datetime(1899, 12, 30) + timedelta(days=float(v))
        except (OverflowError, ValueError):
            return None
    return None


